-- Carga inicial das questoes (gerado de questoes.json)
on conflict (id) do update set disciplina=excluded.disciplina, assunto=excluded.assunto, banca=excluded.banca, concurso=excluded.concurso, ano=excluded.ano, origem=excluded.origem, enunciado=excluded.enunciado, gabarito=excluded.gabarito, forma_correta=excluded.forma_correta, justificativa=excluded.justificativa, para_fixar=excluded.para_fixar, para_fixar_chips=excluded.para_fixar_chips, para_fixar_nota=excluded.para_fixar_nota;
