insert into questoes (id,disciplina,assunto,banca,concurso,ano,origem,enunciado,gabarito,forma_correta,justificativa,para_fixar,para_fixar_chips,para_fixar_nota) values
('crim01','Criminalística','Balística','FEPESE','PCISC/SC',2026,'original','Quanto maior o calibre da arma de fogo, maior será a velocidade que o seu projétil atingirá ao sair do cano.','E','A velocidade do projétil depende sobretudo do tipo de pólvora e do comprimento do cano — não do calibre isoladamente. A pólvora de queima lenta mantém a aceleração do projétil por mais tempo, sendo melhor aproveitada em armas de cano longo.','Calibre é a medida do diâmetro do projétil/alma do cano, não um indicador direto de velocidade de saída. Armas de cano longo com pólvora de queima lenta aproveitam mais tempo de aceleração antes do projétil deixar o cano.','Velocidade = pólvora certa + cano comprido, não calibre grande.',null,null),
('crim02','Criminalística','Cadeia de Custódia','FEPESE','PCISC/SC',2026,'original','Em caso de suspeita de maus-tratos a animais, a cadeia de custódia dos vestígios coletados no local do crime pode ser iniciada apenas no momento da entrega ao laboratório de perícia, sendo dispensável o registro do momento da coleta.','E','A cadeia de custódia tem início no reconhecimento e na coleta do vestígio, ainda no local de crime — não apenas na entrega ao laboratório.','O art. 158-B do CPP define a cadeia de custódia como o conjunto de procedimentos que visa manter e documentar a história cronológica do vestígio, começando pelo reconhecimento do vestígio ainda no local de crime. Omitir o registro do momento da coleta compromete a rastreabilidade exigida pela norma.',null,'["Reconhecimento","Coleta","Acondicionamento","Transporte","Laboratório"]'::jsonb,'A cadeia começa no local, não no laboratório.'),
('crim03','Criminalística','Exame de corpo de delito','FEPESE','PCISC/SC',2026,'original','O exame de corpo de delito poderá ser feito em qualquer dia e a qualquer hora.','C',null,'O art. 161 do CPP estabelece expressamente que o exame de corpo de delito pode ser realizado a qualquer dia e hora, dada a urgência de preservar vestígios que se degradam com o tempo.','Corpo de delito não espera expediente — vestígio não tira folga.',null,null),
('crim04','Criminalística','Exame de corpo de delito','FEPESE','PCISC/SC',2026,'original','O agente público deve dar prioridade à realização do exame de corpo de delito quando o delito envolver violência doméstica ou contra a mulher.','C',null,'A legislação de proteção à mulher (em linha com a Lei Maria da Penha e alterações no CPP) determina tratamento prioritário para perícias em casos de violência doméstica, dada a urgência probatória e o risco de reiteração.','Violência doméstica fura fila de perícia — é prioridade legal, não favor.',null,null),
('legal01','Medicina Legal','Asfixiologia forense','FEPESE','PCISC/SC',2026,'original','A asfixiologia forense é definida como o estudo das mortes por privação de oxigênio, analisando mecanismos e sinais post-mortem para diferenciar causas criminosas de acidentais em perícias.','C',null,'É exatamente esse o objeto da asfixiologia forense: mecanismo de morte por hipóxia (enforcamento, estrangulamento, sufocamento, afogamento etc.) e a leitura dos sinais post-mortem para orientar a qualificação jurídica do fato (homicídio, acidente, suicídio).','Asfixiologia = ciência do ''por que faltou ar'' aplicada à investigação.',null,null),
('legal02','Medicina Legal','Traumatologia forense','FEPESE','PCISC/SC',2026,'original','A traumatologia forense estuda as lesões corporais e suas consequências jurídicas, permitindo identificar a causalidade do dano em contextos criminais.','C',null,'Traumatologia forense é o ramo que correlaciona o tipo de lesão ao instrumento e à dinâmica do evento, fornecendo o nexo causal técnico que sustenta a tipificação penal (lesão corporal, homicídio etc.).','Toda lesão ''conta uma história'' — a traumatologia forense é quem traduz.',null,null),
('legal03','Medicina Legal','Lesões — mecanismo','FEPESE','PCISC/SC',2026,'original','Lesões incisas caracterizam-se por serem irregulares, com esmagamento tecidual, típicas de impactos contundentes.','E','Essa descrição corresponde às lesões contusas, não às incisas. Lesões incisas são ferimentos lineares, de bordas regulares e pouca perda tecidual, produzidos por agentes cortantes (armas brancas).','O enunciado inverteu os conceitos: ''irregular com esmagamento'' é a marca da lesão contusa (agente rombo); a lesão incisa é limpa, linear e regular, característica de instrumento cortante.','Incisa = corte limpo e reto. Contusa = irregular e esmagada.',null,null),
('pen01','Direito Penal','Crimes contra o patrimônio','FEPESE','PCISC/SC',2026,'original','O crime de furto se consuma quando o agente da infração penal passa a ter o poder sobre o objeto do furto.','C',null,'Prevalece o entendimento (inclusive sumulado pelo STJ, Súmula 582) de que o furto se consuma com a posse de fato sobre a coisa subtraída, ainda que breve e vigiada, sendo dispensável a posse mansa e pacífica ou o afastamento do local.','Furto consuma no ''agora é meu'', não precisa fugir com sucesso.',null,null),
('pen02','Direito Penal','Culpabilidade','FEPESE','PCISC/SC',2026,'original','A culpabilidade do agente poderá ser excluída em razão de obediência hierárquica.','C',null,'O art. 22 do Código Penal prevê a obediência hierárquica à ordem não manifestamente ilegal de superior como causa de exclusão da culpabilidade (inexigibilidade de conduta diversa), respondendo apenas quem deu a ordem.','Ordem não manifestamente ilegal + hierarquia = culpa some do subordinado.',null,null),
('pen03','Direito Penal','Sujeitos da infração penal','FEPESE','PCISC/SC',2026,'original','O Estado, cuja norma penal foi violada, é o sujeito passivo formal (constante) de uma infração penal.','C',null,'Todo crime tem o Estado como sujeito passivo formal/constante, por ser o titular do ius puniendi violado; o sujeito passivo material (eventual) é a vítima direta do bem jurídico atingido, que pode ou não existir a depender do delito.','Passivo formal é sempre o Estado; passivo material é quem sofreu de fato.',null,null),
('ppen01','Direito Processual Penal','Inquérito policial','FEPESE','PCISC/SC',2026,'original','Todos os atos e procedimentos realizados ao longo do inquérito policial deverão ser documentados.','C',null,'A documentação integral dos atos do inquérito é exigência do próprio CPP, garantindo a rastreabilidade da investigação e servindo de base às fases seguintes (denúncia, instrução processual).','Inquérito sem registro escrito não vale como prova depois.',null,null),
('ppen02','Direito Processual Penal','Inquérito policial','FEPESE','PCISC/SC',2026,'original','O inquérito policial é um procedimento de natureza administrativa destinado à reunião de informações preliminares que possibilitem o ajuizamento ou não de uma ação penal.','C',null,'Natureza administrativa (não jurisdicional), inquisitivo e preparatório: reúne autoria e materialidade para subsidiar a decisão do titular da ação penal — em regra o Ministério Público — sobre oferecer ou não a denúncia.','Inquérito não julga, só instrui quem vai decidir se processa.',null,null),
('const01','Direito Constitucional','Nacionalidade','FEPESE','PCISC/SC',2026,'original','São cargos privativos de brasileiros natos o de Ministro de Estado da Fazenda e o de Ministro do Superior Tribunal de Justiça, além da Presidência do Senado Federal e da Câmara dos Deputados.','E','Só a Presidência do Senado Federal e da Câmara dos Deputados, entre os citados, são privativas de natos. O art. 12, §3º, da CF lista: Presidente e Vice-Presidente da República, Presidente da Câmara, Presidente do Senado, Ministro do STF (não do STJ), carreira diplomática, oficial das Forças Armadas e Ministro de Estado da Defesa (não da Fazenda).','O rol do art. 12, §3º da CF é taxativo e específico: Ministro da Defesa entra, Ministro da Fazenda não; Ministro do STF entra, do STJ não. É pegadinha clássica trocar STF por STJ e Defesa por outra pasta.','Decore o rol dos 7: PR, VP, Câmara, Senado, STF, diplomata, militar + Ministro da Defesa.',null,null),
('adm01','Direito Administrativo','Responsabilidade civil do Estado','FEPESE','PCISC/SC',2026,'original','A responsabilidade civil objetiva do Estado não se confunde com a responsabilidade subjetiva dos seus agentes, sendo esta última pressuposto da ação regressiva.','C',null,'O Estado responde objetivamente perante o terceiro lesado (teoria do risco administrativo); já a ação regressiva contra o agente público exige a demonstração de dolo ou culpa (responsabilidade subjetiva) daquele agente.','Estado paga sem discutir culpa; pra cobrar do servidor depois, aí sim precisa provar culpa.',null,null),
('adm02','Direito Administrativo','Improbidade administrativa','FEPESE','PCISC/SC',2026,'original','A voluntariedade não é motivo suficiente para caracterizar um ato de improbidade administrativa.','C',null,'Após a Lei 14.230/2021, a improbidade administrativa exige dolo específico (vontade de atingir o resultado ilícito), não bastando a mera voluntariedade da conduta — é preciso a intenção de violar o dever de probidade.','Só ''ter feito de propósito'' não basta — improbidade hoje pede dolo específico.',null,null),
('vet01','Medicina Veterinária Forense','Causas de morte violenta','FEPESE','PCISC/SC',2026,'original','São exemplos de causa de morte violenta em animais: trauma contuso, eletrocussão e asfixia por enforcamento.','C',null,'Causa de morte violenta é toda morte de origem externa/traumática (trauma, eletrocussão, asfixia mecânica), em contraposição às causas naturais (doenças, neoplasias, insuficiências orgânicas espontâneas).','Violenta = veio de fora (trauma/choque/asfixia). Natural = veio de dentro do corpo.',null,null),
('vet02','Medicina Veterinária Forense','Necropsia','AOCP','Politec-PE',2024,'adaptada','Na necropsia veterinária realizada para fins periciais, o exame deve ser conduzido o mais brevemente possível após a morte, a fim de minimizar alterações cadavéricas que possam mascarar achados de interesse pericial.','C',null,'Os fenômenos cadavéricos transformativos — autólise, putrefação — avançam mais rápido em animais de pequeno porte do que no ser humano. Quanto maior o intervalo pós-morte (IPM), maior a chance de achados como equimoses, hemorragias e lesões de tecidos moles serem descaracterizados.','Necropsia forense é corrida contra o relógio: quanto antes, menos autólise mascarando o vestígio.',null,null),
('vet03','Medicina Veterinária Forense','Cronotanatognose e fenômenos cadavéricos','FEPESE','PCISC/SC',2026,'original','A putrefação é um fenômeno transformador destrutivo, condicionado por fatores extrínsecos e intrínsecos, sendo a mancha verde abdominal (ou esternal, em algumas espécies) um de seus primeiros sinais.','C',null,'A putrefação é o principal fenômeno destrutivo pós-morte, com fases sucessivas (cromática, gasosa, coliquativa, esqueletização); a mancha verde é classicamente o primeiro sinal visível da fase cromática, surgindo tipicamente entre 18-24h em condições ambientes moderadas, variando com temperatura e espécie.','Mancha verde = primeiro aviso visual do relógio da putrefação começando a andar.',null,null),
('vet04','Medicina Veterinária Forense','Cronotanatognose e fenômenos cadavéricos','FEPESE','PCISC/SC',2026,'original','A coloração verde da putrefação decorre da reação do gás sulfídrico, de origem bacteriana intestinal, com a hemoglobina, formando sulfemetoglobina na parede abdominal.','C',null,'A flora bacteriana intestinal produz gás sulfídrico (H2S), que se combina com a hemoglobina liberada dos vasos, formando sulfemetoglobina — pigmento esverdeado responsável pela mancha verde abdominal característica.','Bactéria do intestino + hemoglobina = gás + pigmento verde na barriga.',null,null),
('vet05','Medicina Veterinária Forense','Toxicologia forense — amostras','FEPESE','PCISC/SC',2026,'original','Diante de suspeita de intoxicação aguda em necropsia, o conjunto de amostras prioritário e mais completo para análise toxicológica é: conteúdo gástrico, um fragmento de fígado, um fragmento de rim, urina e sangue total (preferencialmente da cavidade cardíaca).','C',null,'Esse conjunto cobre a via de entrada (conteúdo gástrico), os principais órgãos metabolizadores/excretores (fígado, rim) e a matriz sistêmica (sangue, urina), maximizando a chance de identificar o agente e sua rota metabólica.','Estômago (entrada) + fígado/rim (metabolismo) + sangue/urina (circulação) = kit completo.',null,null),
('vet06','Medicina Veterinária Forense','Entomologia forense e IPM','FEPESE','PCISC/SC',2026,'original','Em uma carcaça a cerca de 27°C, com massas de larvas de Calliphoridae em terceiro ínstar (L3) e presença de besouros Silphidae predando essas larvas, o Intervalo Pós-Morte mais provável está entre 4 e 7 dias.','C',null,'A colonização por Calliphoridae já em L3 (último estágio larval) indica alguns dias de decomposição ativa, e a chegada da segunda onda de colonizadores (Silphidae, predadores) reforça uma janela de aproximadamente 4 a 7 dias — sob temperatura considerada nesse cálculo (~27°C acelera o desenvolvimento em relação a climas frios).','1ª onda em L3 + 2ª onda já chegando = pense em dias (4-7), não em horas.',null,null),
('vet07','Medicina Veterinária Forense','Traumatologia forense veterinária','FEPESE','PCISC/SC',2026,'original','O estrangulamento diferencia-se do enforcamento por ser uma constrição do pescoço exercida por um laço acionado por força externa (mãos, braços ou instrumento), e não pelo peso do próprio corpo do animal.','C',null,'A distinção clássica em asfixiologia forense: no enforcamento a força constritora é o próprio peso do corpo suspenso; no estrangulamento a força é externa, aplicada por um agente diferente do peso corporal da vítima.','Enforcamento: o peso do corpo aperta. Estrangulamento: alguém (ou algo) de fora aperta.',null,null),
('vet08','Medicina Veterinária Forense','Maus-tratos e Teoria do Elo','FEPESE','PCISC/SC',2026,'original','Segundo a Teoria do Elo, o médico-veterinário atua como sentinela, pois a identificação de lesões não acidentais em animais pode ser indicador precoce de violência doméstica, abuso infantil ou maus-tratos a idosos.','C',null,'A Teoria do Elo (link theory) é sustentada por correlação epidemiológica e comportamental entre violência contra animais e violência interpessoal no mesmo ambiente familiar; por isso o veterinário pericial tem papel de alerta precoce (''sentinela'') para a rede de proteção humana.','Animal maltratado em casa pode ser o primeiro sinal visível de uma casa violenta.',null,null),
('vet09','Medicina Veterinária Forense','Cadeia de custódia','FEPESE','PCISC/SC',2026,'original','A principal finalidade da cadeia de custódia é garantir a rastreabilidade e a integridade da prova, documentando todas as pessoas que tiveram acesso ao vestígio desde a coleta até o descarte.','C',null,'Rastreabilidade (quem, quando, onde) e integridade (sem alteração/substituição) são os dois pilares da cadeia de custódia, aplicáveis igualmente a perícias com animais vivos ou mortos.','Cadeia de custódia = ''quem tocou, quando e por quê'', do início ao fim, sem furo.',null,null),
('vet10','Medicina Veterinária Forense','Toxicologia veterinária — antagonistas','FEPESE','PCISC/SC',2026,'original','Diante de intoxicação por Xilazina (agonista alfa-2 adrenérgico) em animal vivo, o antagonista específico indicado para reversão imediata dos efeitos é a Ioimbina.','C',null,'A Ioimbina é o antagonista alfa-2 adrenérgico de escolha para reverter os efeitos sedativos da Xilazina — distinto de Naloxona (opioides), Flumazenil (benzodiazepínicos) e Atropina (efeitos muscarínicos).','Xilazina entra, Ioimbina reverte — são o par certo, não confundir com Naloxona/Flumazenil.',null,null),
('vet11a','Medicina Veterinária Forense','Toxicologia forense — espécie felina','FEPESE','PCISC/SC',2026,'original','Em felinos, a deficiência da enzima glucuroniltransferase torna o Paracetamol especialmente tóxico, sendo o metabólito reativo NAPQI responsável por estresse oxidativo nas hemácias (formação de corpúsculos de Heinz, metemoglobinemia) e hepatotoxicidade.','C',null,'Gatos metabolizam mal substâncias que dependem de glucuronidação; o Paracetamol gera NAPQI em excesso, causando dano oxidativo eritrocitário (Heinz, metemoglobinemia com sangue achocolatado) e necrose hepática centrolobular — quadro clássico de intoxicação acidental/dolosa por analgésico humano em felinos.','Gato + paracetamol humano = combinação perigosa: falta a enzima que desintoxica.',null,null),
('vet11','Medicina Veterinária Forense','Doenças de notificação obrigatória','FEPESE','PCISC/SC',2026,'original','Um surto em suínos jovens com mortalidade elevada, febre alta, pústulas cutâneas hemorrágicas e sinais nervosos exige notificação compulsória e imediata ao Serviço Veterinário Oficial, com suspeita principal de Peste Suína Clássica.','C',null,'A Peste Suína Clássica é doença de notificação compulsória imediata no Brasil por seu impacto sanitário e econômico; o quadro descrito (mortalidade alta em jovens, sinais hemorrágicos e nervosos) é clássico da doença e não pode aguardar confirmação laboratorial para ser comunicado.','Suspeita de PSC não espera exame — comunica primeiro, confirma depois.',null,null),
('vet12','Medicina Veterinária Forense','Crimes contra a fauna','FEPESE','PCISC/SC',2026,'original','Manter um papagaio-verdadeiro (Amazona aestiva) sem anilha e registro, com sinais de estresse crônico e lesões por contenção inadequada, configura crime de maus-tratos e manutenção irregular de fauna silvestre, independentemente de a espécie ser considerada de baixa mobilidade ou adaptada ao convívio humano.','C',null,'A Lei de Crimes Ambientais (9.605/98) não condiciona a tipificação à docilidade ou popularidade da espécie como animal de estimação; a ausência de registro/anilha e a presença de lesões por manejo inadequado configuram, cumulativamente, maus-tratos e manutenção irregular de fauna silvestre.','Fofura da espécie não vira licença — sem anilha e com lesão, é crime do mesmo jeito.',null,null)
